      req.on('data', (c) => (data += c));
      req.on('end', () => {
        const n = { id: notes.size + 1, ...JSON.parse(data) };
        notes.set(n.id, n);
        send(201, n);
      });
      return;
    }
    const m = /^\/notes\/(\d+)$/.exec(url.pathname);
    if (m) return notes.has(+m[1]) ? send(200, notes.get(+m[1])) : send(404, { error: 'not found' });
    if (url.pathname === '/search') {
      const q = url.searchParams.get('q') ?? '';
      return send(200, [...notes.values()].filter((n) => n.title.includes(q)));
    }
    send(404, { error: 'not found' });
  });
}

