import { type Result, ok, err } from './result.ts';
import { searchNotes } from './search.ts';

export interface ApiRequest { method: string; pathname: string; query: URLSearchParams; bodyText: string }
export interface ApiResponse { status: number; body: unknown }

interface NoteInput { title: string; body: string }

const reply = (status: number, body: unknown): ApiResponse => ({ status, body });
const fail = (status: number, error: string): ApiResponse => reply(status, { error });
const notFound = (): ApiResponse => fail(404, 'not found');

function parseJson(text: string): Result<unknown> {
  try {
    return ok(JSON.parse(text) as unknown);
  } catch {
    return err('invalid JSON');
  }
}

export function parseNoteInput(text: string): Result<NoteInput> {
  const parsed = parseJson(text);
  if (!parsed.ok) return parsed;
  const v = parsed.value;
  if (typeof v !== 'object' || v === null || Array.isArray(v)) return err('body must be a JSON object');
  const { title, body = '' } = v as Record<string, unknown>;
  if (typeof title !== 'string') return err('title must be a string');
  if (typeof body !== 'string') return err('body must be a string');
  return ok({ title, body });
}

function createNote(req: ApiRequest, store: NoteStore): ApiResponse {
  const input = parseNoteInput(req.bodyText);
  if (!input.ok) return fail(400, input.error);
  const added = store.add(input.value.title, input.value.body);
  return added.ok ? reply(201, added.value) : fail(400, added.error);
}

const listNotes = (_req: ApiRequest, store: NoteStore): ApiResponse => reply(200, store.list());

function getNote(id: string, store: NoteStore): ApiResponse {
  if (!/^[1-9][0-9]*$/.test(id)) return notFound();
  const found = store.get(Number(id));
  return found.ok ? reply(200, found.value) : notFound();
}

function search(req: ApiRequest, store: NoteStore): ApiResponse {
  const found = searchNotes(store.list(), req.query.get('q') ?? '');
  return found.ok ? reply(200, found.value) : fail(400, found.error);
}

const health = (): ApiResponse => reply(200, { status: 'ok' });

type RouteHandler = (req: ApiRequest, store: NoteStore, params: string[]) => ApiResponse;
interface Route { method: string; pattern: RegExp; run: RouteHandler }

const ROUTES: Route[] = [
  { method: 'GET', pattern: /^\/health$/, run: health },
  { method: 'POST', pattern: /^\/notes$/, run: createNote },
  { method: 'GET', pattern: /^\/notes$/, run: listNotes },
  { method: 'GET', pattern: /^\/notes\/([^/]+)$/, run: (_r, store, p) => getNote(p[0], store) },
  { method: 'GET', pattern: /^\/search$/, run: search },
];

export function handle(req: ApiRequest, store: NoteStore): ApiResponse {
  for (const route of ROUTES) {
    const m = route.method === req.method ? route.pattern.exec(req.pathname) : null;
    if (m) return route.run(req, store, m.slice(1));
  }
  return notFound();
}
